function routeToModel(tenant, latencyMs, remainingTokens){
  const budgetFrac = remainingTokens / tenant.dailyBudget;
  if (budgetFrac > 0.5 && latencyMs < 80) return 'fast';
  if (latencyMs < 120) return 'balanced';
  return 'accurate';
}
```

